  Lemma del_agree : forall A M M' p n lo hi a k,
    frame_eq (fun x => owned MI A x \/ (p <= x < p + n) \/ zwin lo hi x \/ errno_win L x) M M' ->
    (forall x, a <= x < a + k -> ~ owned MI A x) -> apart a k p n -> (a + k <= lo \/ hi <= a) ->
    0 <= a -> a + k < 2 ^ 64 ->
