    Lemma zloop : forall (k : nat) (bl n i : Z) Mi R (Mw : mem) model,
      Z.of_nat k = n - i -> 0 <= i < n -> 0 < bl -> bl + 8 * n <= alloc_ceiling -> mstd model ->
      base_ok R -> getr R 10%bv = Z_to_bv 64 n -> getr R 11%bv = Z_to_bv 64 bl ->
      getr R 12%bv = Z_to_bv 64 (8 * i) -> getr R 13%bv = Z_to_bv 64 i -> getr R 14%bv = Z_to_bv 64 (2 ^ 64 - 1 - bl) ->
      (forall x : word, ~ (bl <= bv_unsigned x < bl + 8 * n) -> Mi x = Mw x) -> (forall x : word, Mw x <> None -> Mi x <> None) ->
      (forall j, 0 <= j < i -> cell8 SEGS Mi (bl + 8 * j) 0) -> defined Mi bl (8 * n) ->
      (forall M' R', base_ok R' ->
          (forall x : word, ~ (bl <= bv_unsigned x < bl + 8 * n) -> M' x = Mw x) -> (forall x : word, Mw x <> None -> M' x <> None) ->
          (forall j, 0 <= j < n -> cell8 SEGS M' (bl + 8 * j) 0) ->
          srealizes SEGS (cfg fx R' ZEND M' model) K) ->
      srealizes SEGS (cfg fx R ZL_PC Mi model) K.
Proof using AC L MI ST DEL_STACK DEL_STACK_nn fx A0 s R0 M0 model0 sp ret obj1 obj2 K CB.
Ltac scZ DEFp bl i :=
        split_scs;
        first [ eapply (sc_trap_srl _ _ _ _ i 60); [evs; reflexivity | lia | lia]
              | eapply (sc_trap_notlt _ _ _ _ _ bl (8 * i)); [evs; reflexivity | evs; reflexivity | lia | lia | lia]
