    Record mid (A : AS MI) (M : mem) (model : Model) (R : bvmap 5 word) (ops : list lop) (F : Z -> Prop) : Prop := MID {
      md_ainv : ainv MI A M model;
      md_mstd : mstd model;
      md_fs : m_fs model = m_fs model0;
      md_fds : m_fds model = m_fds model0;
      md_base : base_ok R;
      md_frame : frame M;
      md_def : defined M (sp - 32 - DEL_STACK) (32 + DEL_STACK);
      md_eff : eff MI A0 A M0 M W F;
      md_lap : lapply (live MI A0) ops (live MI A);
      md_win : forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A a;
      md_own1 : forall i, 0 <= i < 40 -> ~ owned MI A (obj1 + i);
      md_own2 : forall i, 0 <= i < 40 -> ~ owned MI A (obj2 + i);
      md_hdef1 : defined M obj1 40;
      md_hdef2 : defined M obj2 40;

      md_nodes2 : forall p k v, In (p, (k, v)) ents2 -> agree_on M0 M p NS;
      md_bkt2 : bc2 <> 0 -> agree_on M0 M bl2 (8 * bc2);
      md_live2 : forall p n, In (p, n) (umap_blocks NS bl2 bc2 ents2) -> In (p, n) (live MI A)
    }.

#[local] Definition HTHMva2U1_0 : list kentry := [KDisj (SA (EVar 32) 0) (ELit 40) (SA (EVar 33) 0) (ELit 40)].
    Lemma phaseB : forall A1 M1 model1 R1,
      mid A1 M1 model1 R1 (map (fun e => LDel (fst e)) ents1) FOOT1 ->
      cell8 SEGS M1 obj1 bl1 -> cell8 SEGS M1 (obj1 + 8) bc1 -> cell8 SEGS M1 (obj1 + 16) 0 ->
      cell8 SEGS M1 (obj1 + 24) 0 -> cell4 SEGS M1 (obj1 + 32) 0x3f800000 ->
      (bc1 <> 0 -> In (bl1, 8 * bc1) (live MI A1)) ->
      cell8 SEGS M1 obj2 bl2 -> cell8 SEGS M1 (obj2 + 8) bc2 -> cell8 SEGS M1 (obj2 + 16) (hdaddr ents2) ->
      cell8 SEGS M1 (obj2 + 24) (Zlength ents2) -> cell4 SEGS M1 (obj2 + 32) 0x3f800000 ->
      (forall A3 M3 model3 R3,
          mid A3 M3 model3 R3 (free_ops bl1 bc1 ents1) FOOTB ->
          cell8 SEGS M3 obj1 bl2 -> cell8 SEGS M3 (obj1 + 8) bc1 -> cell8 SEGS M3 (obj1 + 16) 0 ->
          cell8 SEGS M3 (obj1 + 24) 0 -> cell4 SEGS M3 (obj1 + 32) 0x3f800000 ->
          cell8 SEGS M3 obj2 0 -> cell8 SEGS M3 (obj2 + 8) bc2 -> cell8 SEGS M3 (obj2 + 16) (hdaddr ents2) ->
          cell8 SEGS M3 (obj2 + 24) (Zlength ents2) -> cell4 SEGS M3 (obj2 + 32) 0x3f800000 ->
          srealizes SEGS (cfg fx R3 DRET2 M3 model3) K) ->
